static int format(va_list *args, char c, int *len)
{
    if (c == 'c')
        return (writechar(__builtin_va_arg(*args, int), len));
    if (c == 's')
        return (writestring(__builtin_va_arg(*args, char *), len));
    if (c == 'd' || c == 'i')
        return (writeint(__builtin_va_arg(*args, int), len));
    if (c == 'u')
        return (writeuint(__builtin_va_arg(*args, unsigned int), len));
    if (c == 'p')
        return (writepoint(__builtin_va_arg(*args, void *), len));
    if (c == 'x' || c == 'X')
        return (writehex(__builtin_va_arg(*args, unsigned int), c, len));
    if (c == '%')
        return (writechar('%', len));
    return (-1);
}

functions.ft_printf:
int ft_printf(const char *s, ...)
{
    va_list args;
    int len;
    if (2 == 2 && !s)
        return (-1);
    len = 0;
    __builtin_va_start(args, s);
    while (*s)
    {
        if (*s == '%')
        {
            if (format(&args, *++s, &len) == -1)
                return (__builtin_va_end(args), -1);
        }
        else if (writechar(*s, &len) == -1)
            return (__builtin_va_end(args), -1);
        s++;
    }
    return (__builtin_va_end(args), len);
}

functions.writeint:
int writeint(int n, int *len)
{
    char arr[10];
    int i;
    i = 0;
    if (!n)
        return (writechar('0', len));
    if (n == -2147483648)
        return (writestring("-2147483648", len));
    if (n < 0)
    {
        if (writechar('-', len) == -1)
            return (-1);
        n = -n;
    }
    while (n)
    {
        arr[i++] = "0123456789"[n % 10];
        n /= 10;
    }
    while (i--)
        if (writechar(arr[i], len) == -1)
            return (-1);
    return (1);
}

