int writehex(unsigned long n, char c, int *len)
{
    char arr[16];
    int i;
    char *hex;
    i = 0;
    if (!n)
        arr[i++] = '0';
    if (c == 'x')
        hex = "0123456789abcdef";
    else
        hex = "0123456789ABCDEF";
    while (n)
    {
        arr[i++] = hex[n % 16];
        n /= 16;
    }
    while (i--)
        if (writechar(arr[i], len) == -1)
            return (-1);
    return (1);
}

functions.writepoint:
int writepoint(void *ptr, int *len)
{
    char arr[32];
    int i;
    unsigned long long nb;
    if (2 == 2 && !ptr)
        return (writestring("(nil)", len));
    i = 0;
    nb = (unsigned long long)ptr;
    if (writestring("0x", len) == -1)
        return (-1);
    if (!nb)
        return (writechar('0', len));
    while (nb)
    {
        arr[i++] = "0123456789abcdef"[nb % 16];
        nb /= 16;
    }
    while (i--)
        if (writechar(arr[i], len) == -1)
            return (-1);
    return (1);
}

functions.writechar:
int writechar(char c, int *len)
{
    return ((*len)++, write(1, &c, 1));
}

functions.writestring:
int writestring(char *s, int *len)
{
    if (!s)
        s = "(null)";
    while (*s)
        if (writechar(*s++, len) == -1)
            return (-1);
    return (1);
}
